using UnityEngine;
using UnityEngine.UI;

namespace UBOAT.Mods.RadioNavigation
{
    /// <summary>
    /// On-screen F-Tafel legend (SEXTANT_PLAN v2.2), toggled by the P key
    /// while the sextant is open. Explains the worksheet fields, the sight
    /// workflow and the game assumptions (refraction / lunar parallax /
    /// horizon dip are not modelled). Built once with the overlay and hidden
    /// until asked for. Legacy UI.Text + OS Arial for Cyrillic glyphs.
    /// </summary>
    internal static class SextantHelpPanel
    {
        private const string HelpText =
            "\u0411\u041B\u0410\u041D\u041A F-TAFEL \u2014 \u0421\u041F\u0420\u0410\u0412\u041A\u0410\n" +
            "\n" +
            "\u041F\u041E\u0421\u041B\u0415\u0414\u041E\u0412\u0410\u0422\u0415\u041B\u042C\u041D\u041E\u0421\u0422\u042C\n" +
            "1. \u041D\u0430\u0432\u0435\u0434\u0438\u0442\u0435 \u0441\u0432\u0435\u0442\u0438\u043B\u043E \u0432 \u0446\u0435\u043D\u0442\u0440 \u043E\u043A\u0443\u043B\u044F\u0440\u0430 \u0438 \u0434\u0435\u0440\u0436\u0438\u0442\u0435 2.5 \u0441 \u2014 \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F \u0438\u043C\u044F.\n" +
            "2. I \u2014 \u0437\u0430\u043F\u0438\u0441\u0430\u0442\u044C \u043D\u0430\u0431\u043B\u044E\u0434\u0435\u043D\u0438\u0435 (\u0421\u043E\u043B\u043D\u0446\u0435, \u041B\u0443\u043D\u0430 \u0438\u043B\u0438 \u0437\u0432\u0435\u0437\u0434\u0430).\n" +
            "3. \u0417\u0430\u043F\u0438\u0448\u0438\u0442\u0435 \u0432\u0442\u043E\u0440\u043E\u0435 \u0441\u0432\u0435\u0442\u0438\u043B\u043E: \u0442\u0440\u0435\u0442\u044C\u0435 I \u0437\u0430\u043C\u0435\u043D\u0438\u0442 \u043D\u0430\u0431\u043B\u044E\u0434\u0435\u043D\u0438\u0435 \u21162.\n" +
            "4. O \u2014 \u043D\u043E\u0432\u0430\u044F \u0441\u0435\u0440\u0438\u044F.\n" +
            "\n" +
            "\u041F\u041E\u041B\u042F \u0411\u041B\u0410\u041D\u041A\u0410\n" +
            "\u03B3 \u2014 \u0437\u0432\u0451\u0437\u0434\u043D\u043E\u0435 \u0432\u0440\u0435\u043C\u044F (GHA Aries)\n" +
            "SHA \u2014 \u0437\u0432\u0451\u0437\u0434\u043D\u044B\u0439 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0443\u0433\u043E\u043B \u0441\u0432\u0435\u0442\u0438\u043B\u0430\n" +
            "GHA \u2014 \u0433\u0440\u0438\u043D\u0432\u0438\u0447\u0441\u043A\u0438\u0439 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0443\u0433\u043E\u043B \u0441\u0432\u0435\u0442\u0438\u043B\u0430\n" +
            "\u03BBg \u2014 \u0434\u043E\u043B\u0433\u043E\u0442\u0430 \u0441\u0447\u0438\u0441\u043B\u0438\u043C\u043E\u0433\u043E \u043C\u0435\u0441\u0442\u0430\n" +
            "LHA \u2014 \u043C\u0435\u0441\u0442\u043D\u044B\u0439 \u0447\u0430\u0441\u043E\u0432\u043E\u0439 \u0443\u0433\u043E\u043B; \u043A\u0432. \u2014 \u043A\u0432\u0430\u0434\u0440\u0430\u043D\u0442, W/O = \u0432\u0435\u0441\u0442/\u043E\u0441\u0442\n" +
            "\u03B4 \u2014 \u0441\u043A\u043B\u043E\u043D\u0435\u043D\u0438\u0435 \u0441\u0432\u0435\u0442\u0438\u043B\u0430\n" +
            "hb \u2014 \u0438\u0437\u043C\u0435\u0440\u0435\u043D\u043D\u0430\u044F \u0432\u044B\u0441\u043E\u0442\u0430, h1 \u2014 \u0432\u044B\u0447\u0438\u0441\u043B\u0435\u043D\u043D\u0430\u044F \u0432\u044B\u0441\u043E\u0442\u0430\n" +
            "Az \u2014 \u0430\u0437\u0438\u043C\u0443\u0442, a \u2014 \u0438\u043D\u0442\u0435\u0440\u0446\u0435\u043F\u0442 (hb\u2212h1), NM\n" +
            "\n" +
            "\u0424\u0418\u041A\u0421\n" +
            "FIX \u2014 \u0448\u0438\u0440\u043E\u0442\u0430 \u0438 \u0434\u043E\u043B\u0433\u043E\u0442\u0430 \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043D\u0438\u044F \u0434\u0432\u0443\u0445 \u043B\u0438\u043D\u0438\u0439.\n" +
            "\u0394 \u043E\u0442 \u043C\u0435\u0441\u0442\u0430 \u0438\u0433\u0440\u044B (\u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430) \u2014 \u0440\u0430\u0441\u0445\u043E\u0436\u0434\u0435\u043D\u0438\u0435 \u0444\u0438\u043A\u0441\u0430 \u0441 \u043F\u043E\u0437\u0438\u0446\u0438\u0435\u0439 \u0438\u0433\u0440\u044B; \u044D\u0442\u043E \u0441\u0430\u043C\u043E\u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0437\u0430\u043C\u0435\u0440\u043E\u0432, \u0430 \u043D\u0435 \u043D\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u043E\u043D\u043D\u0430\u044F \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E\u0441\u0442\u044C.\n" +
            "\u0413\u0435\u043E\u043C\u0435\u0442\u0440\u0438\u044F \u2014 \u0443\u0433\u043E\u043B \u043F\u0435\u0440\u0435\u0441\u0435\u0447\u0435\u043D\u0438\u044F \u043B\u0438\u043D\u0438\u0439: >30\u00B0 \u0445\u043E\u0440\u043E\u0448\u043E, 15\u201330\u00B0 \u043F\u043E\u0441\u0440\u0435\u0434\u0441\u0442\u0432\u0435\u043D\u043D\u043E, <15\u00B0 \u0441\u043B\u0430\u0431\u043E.\n" +
            "\n" +
            "\u0414\u041E\u041F\u0423\u0429\u0415\u041D\u0418\u042F \u0418\u0413\u0420\u042B\n" +
            "\u0418\u0433\u0440\u0430 \u043D\u0435 \u043C\u043E\u0434\u0435\u043B\u0438\u0440\u0443\u0435\u0442 \u0440\u0435\u0444\u0440\u0430\u043A\u0446\u0438\u044E, \u043F\u0430\u0440\u0430\u043B\u043B\u0430\u043A\u0441 \u041B\u0443\u043D\u044B \u0438 \u043D\u0430\u043A\u043B\u043E\u043D \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430 (dip).\n" +
            "\u042D\u0444\u0435\u043C\u0435\u0440\u0438\u0434\u0430 \u041B\u0443\u043D\u044B \u043D\u0438\u0437\u043A\u043E\u0442\u043E\u0447\u043D\u0430\u044F: \u00B10.3\u00B0 (\u043E\u043A\u043E\u043B\u043E 18 NM).\n" +
            "\u041B\u0443\u043D\u0430 \u0438 \u0421\u043E\u043B\u043D\u0446\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u044E\u0442 \u043E\u0431\u0449\u0443\u044E \u043F\u043E\u043F\u0440\u0430\u0432\u043A\u0443 \u0432\u0440\u0435\u043C\u0435\u043D\u0438 (\u0394t).\n" +
            "\u0417\u0432\u0451\u0437\u0434\u044B \u2014 \u043A\u0430\u0442\u0430\u043B\u043E\u0433 J1942 \u0431\u0435\u0437 \u043F\u0440\u0435\u0446\u0435\u0441\u0441\u0438\u0438; \u0437\u0430\u043C\u0435\u0440 \u0433\u0435\u043E\u0446\u0435\u043D\u0442\u0440\u0438\u0447\u0435\u0441\u043A\u0438\u0439.\n" +
            "\u041F\u043B\u0430\u043D\u0435\u0442\u044B (\u0412\u0435\u043D\u0435\u0440\u0430, \u042E\u043F\u0438\u0442\u0435\u0440, \u0421\u0430\u0442\u0443\u0440\u043D, \u041C\u0430\u0440\u0441) \u0432\u0438\u0434\u043D\u044B, \u043D\u043E \u0432 \u0441\u0447\u0438\u0441\u043B\u0435\u043D\u0438\u0438 \u043D\u0435 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u044E\u0442.\n" +
            "\n" +
            "P \u2014 \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u0441\u043F\u0440\u0430\u0432\u043A\u0443 \u00B7 Z \u2014 \u0432\u044B\u0445\u043E\u0434";

        /// <summary>Builds the hidden help panel under the overlay canvas.</summary>
        public static GameObject Build(GameObject canvasRoot)
        {
            GameObject panel = new GameObject("HelpPanel", typeof(Image));
            panel.transform.SetParent(canvasRoot.transform, false);
            RectTransform rect = panel.GetComponent<RectTransform>();
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            rect.sizeDelta = new Vector2(1200f, 720f);
            rect.anchoredPosition = Vector2.zero;

            Image background = panel.GetComponent<Image>();
            background.color = new Color(0f, 0f, 0f, 0.93f);
            background.raycastTarget = true;

            Text text = SextantColumnsBuilder.MakeLabel(canvasRoot, "HelpText", 16,
                TextAnchor.UpperLeft, new Color(0.9f, 0.92f, 0.9f));
            text.text = HelpText;
            text.horizontalOverflow = HorizontalWrapMode.Wrap;
            text.rectTransform.SetParent(rect, false);
            RectTransform textRect = text.rectTransform;
            textRect.anchorMin = Vector2.zero;
            textRect.anchorMax = Vector2.one;
            textRect.offsetMin = new Vector2(30f, 24f);
            textRect.offsetMax = new Vector2(-30f, -24f);

            panel.SetActive(false);
            return panel;
        }
    }
}
